const rows = $input.all().map((i) => i.json).filter((j) => j && Object.keys(j).length > 0 && j.id !== undefined);
const total = rows.length;
const escalations = rows.filter((r) => r.escalation_status === "escalated").length;
const aiResolved = rows.filter((r) => r.resolution_status === "resolved").length;
const resolutionRate = total ? Math.round((aiResolved / total) * 1000) / 10 : 0;
const escalationRate = total ? Math.round((escalations / total) * 1000) / 10 : 0;

const avg = (arr) => (arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : 0);
const respTimes = rows.map((r) => Number(r.response_time_ms) || 0).filter((n) => n > 0);
const avgResponseMs = Math.round(avg(respTimes));
const confidences = rows.map((r) => Number(r.ai_confidence) || 0).filter((n) => n > 0);
const avgConfidence = Math.round(avg(confidences) * 10) / 10;

const tally = (key) => {
  const out = {};
  for (const r of rows) { const k = r[key] || "unknown"; out[k] = (out[k] || 0) + 1; }
  return out;
};
const sentiment = tally("sentiment");
const channels = tally("channel");
const categories = tally("category");
const topTopics = Object.keys(categories)
  .map((k) => ({ topic: k, count: categories[k] }))
  .sort((a, b) => b.count - a.count)
  .slice(0, 5);

const reportDate = $now.minus({ days: 1 }).toFormat('yyyy-MM-dd');
return [{ json: {
  report_date: reportDate,
  total_conversations: total,
  has_data: total > 0,
  ai_resolution_rate: resolutionRate,
  human_escalations: escalations,
  escalation_rate: escalationRate,
  avg_response_time_ms: avgResponseMs,
  avg_response_time_readable: (avgResponseMs / 1000).toFixed(1) + "s",
  avg_ai_confidence: avgConfidence,
  sentiment_breakdown: sentiment,
  channel_usage: channels,
  most_common_topics: topTopics,
} }];

